tape( 'the function returns 0 when N is 0', function test( t ) {
	var AP = new Float64Array( [ 1.0 ] );
	var v;

	v = dlansp( 'row-major', 'M', 'upper', 0, AP );
	t.strictEqual( v, 0.0, 'returns expected value' );

	v = dlansp( 'row-major', '1', 'lower', 0, AP );
	t.strictEqual( v, 0.0, 'returns expected value' );

	v = dlansp( 'row-major', 'F', 'upper', 0, AP );
	t.strictEqual( v, 0.0, 'returns expected value' );

	t.end();
});

tape( 'the function computes the max norm (row-major, upper)', function test( t ) {
	var data;
	var v;

	data = MAX_NORM_ROW_MAJOR_UPPER;
	v = dlansp( data.order, data.norm, data.uplo, data.N, new Float64Array( data.AP ) );
	t.strictEqual( v, data.expected, 'returns expected value' );
	t.end();
});

