tape( 'the function computes the infinity norm (symmetric: normI == norm1)', function test( t ) {
	var one;
	var AP;
	var v;

	AP = new Float64Array( ONE_NORM_ROW_MAJOR_UPPER.AP );
	one = dlansp( 'row-major', '1', 'upper', ONE_NORM_ROW_MAJOR_UPPER.N, AP );
	v = dlansp( 'row-major', 'I', 'upper', ONE_NORM_ROW_MAJOR_UPPER.N, AP );
	t.strictEqual( v, one, 'infinity norm equals one norm (upper)' );

	AP = new Float64Array( ONE_NORM_ROW_MAJOR_LOWER.AP );
	one = dlansp( 'row-major', '1', 'lower', ONE_NORM_ROW_MAJOR_LOWER.N, AP );
	v = dlansp( 'row-major', 'I', 'lower', ONE_NORM_ROW_MAJOR_LOWER.N, AP );
	t.strictEqual( v, one, 'infinity norm equals one norm (lower)' );

	t.end();
});

