tape( 'the function supports norm character aliases', function test( t ) {
	var AP;
	var v;

	AP = new Float64Array( [ 1.0, 2.0, 5.0 ] );

	v = dlansp( 'row-major', 'm', 'upper', 2, AP );
	t.strictEqual( v, 5.0, 'returns expected value for lowercase m' );

	v = dlansp( 'row-major', 'o', 'upper', 2, AP );
	t.strictEqual( v, 7.0, 'returns expected value for lowercase o' );

	v = dlansp( 'row-major', 'i', 'upper', 2, AP );
	t.strictEqual( v, 7.0, 'returns expected value for lowercase i' );

	v = dlansp( 'row-major', 'O', 'upper', 2, AP );
	t.strictEqual( v, 7.0, 'returns expected value for O' );

	v = dlansp( 'row-major', 'f', 'upper', 2, AP );
	isApprox( t, v, dlansp( 'row-major', 'F', 'upper', 2, AP ), 'returns expected value for lowercase f' );

	v = dlansp( 'row-major', 'E', 'upper', 2, AP );
	isApprox( t, v, dlansp( 'row-major', 'F', 'upper', 2, AP ), 'returns expected value for E' );

	v = dlansp( 'row-major', 'e', 'upper', 2, AP );
	isApprox( t, v, dlansp( 'row-major', 'F', 'upper', 2, AP ), 'returns expected value for lowercase e' );

	t.end();
});

