tape( 'the function computes the Frobenius norm if the diagonal contains zeros', function test( t ) {
	var expected;
	var AP;
	var v;

	AP = new Float64Array( [ 0.0, 2.0, 0.0 ] );
	expected = 2.8284271247461903;

	v = dlansp( 'row-major', 'F', 'upper', 2, AP );
	isApprox( t, v, expected, 'returns expected value for upper' );

	v = dlansp( 'row-major', 'F', 'lower', 2, AP );
	isApprox( t, v, expected, 'returns expected value for lower' );

	t.end();
});
